diff --git a/fuzz/README.md b/fuzz/README.md
deleted file mode 100644
index bd93b0a..0000000
--- a/fuzz/README.md
+++ /dev/null
@@ -1,29 +0,0 @@
-# Fuzzing
-
-This directory contains code and test data for fuzz testing picotls with LLVM's [LibFuzzer](http://libfuzzer.info).
-
-## Building the test drivers
-
-To build the fuzz test drivers (AKA "fuzz targets"), pass `-DBUILD_FUZZER=ON` to `cmake`. This this will instrument the binary and build fuzz targets. Note that you must have a version of LLVM Clang installed that supports LibFuzzer in order for this build to succeed.
-
-## Test corpus information
-
-There are seed test corpuses for some fuzz targets included. They are stored in the `fuzz` directory in a subdirectory corresponding to the fuzz target binary name.  See the [LibFuzzer docs](http://llvm.org/docs/LibFuzzer.html) for more information on using seed test corpuses.
-
-## Submitting new seed files
-
-This project welcomes seed files that exercise new paths in the target programs. Before submitting new seed files, please ensure they add coverage to the existing corpus via the driver `-merge` flag. For example:
-
-```
-$ ./fuzz-client-hello-merge=1 ./fuzz/fuzz-client-hello-corpus ./fuzz/my-new-seeds
-```
-
-See the [LibFuzzer docs](http://llvm.org/docs/LibFuzzer.html) for more information on minimizing test corpuses.
-
-## Running the fuzzers
-
-You will likely want to tailor fuzzer options to your execution environment, but here is a basic example of running a fuzzer:
-
-```
-./fuzz-client-hello fuzz/fuzz-client-hello-corpus
-```
diff --git a/fuzz/fuzz-asn1.c b/fuzz/fuzz-asn1.c
deleted file mode 100644
index 068becb..0000000
--- a/fuzz/fuzz-asn1.c
+++ /dev/null
@@ -1,111 +0,0 @@
-#include <stdint.h>
-#include <unistd.h>
-#include <stdlib.h>
-#include <stdio.h>
-#include <stddef.h>
-#include <stdarg.h>
-#include "picotls.h"
-#include "picotls/asn1.h"
-#include "picotls/minicrypto.h"
-
-static struct feeder {
-    const uint8_t *data;
-    size_t size;
-} feeder;
-
-static void feeder_init(const uint8_t *orig_data, size_t orig_size)
-{
-    feeder.data = orig_data;
-    feeder.size = orig_size;
-}
-
-static uint8_t feeder_next_byte(void)
-{
-    if (feeder.size == 0) {
-        return 0;
-    }
-    uint8_t byte = *feeder.data;
-    --feeder.size;
-    ++feeder.data;
-    return byte;
-}
-
-void count_printf(void *ctx, const char *format, ...)
-{
-    int *c = ctx;
-    va_list argptr;
-    va_start(argptr, format);
-    c += vsnprintf(NULL, 0, format, argptr);
-    va_end(argptr);
-    return;
-}
-
-int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
-{
-    int i, counter, indefinite_length, decode_error;
-    ptls_minicrypto_log_ctx_t ctx = {&counter, count_printf};
-    uint8_t *bytes, expected_type;
-    size_t last_byte, bytes_max, byte_index;
-    uint32_t length;
-    uint8_t ret;
-
-    feeder_init(Data, Size);
-
-    bytes_max = (feeder_next_byte() << 8) + feeder_next_byte();
-    if (bytes_max == 0)
-        return 0;
-
-    /* fill the test buffer */
-    bytes = malloc(bytes_max);
-    for (i = 0; i < bytes_max; i++) {
-        bytes[i] = feeder_next_byte();
-    }
-
-    ret = feeder_next_byte() % 4;
-    /* fuzz either ptls_asn1_validation or ptls_asn1_get_expected_type_and_length */
-    if (ret == 0) {
-        ptls_asn1_validation(bytes, bytes_max, &ctx);
-    } else if (ret == 1) {
-        byte_index = (feeder_next_byte() << 8) + feeder_next_byte();
-        byte_index = byte_index % bytes_max;
-        expected_type = feeder_next_byte();
-        ptls_asn1_get_expected_type_and_length(bytes, bytes_max, byte_index, expected_type, &length, &indefinite_length, &last_byte,
-                &decode_error, &ctx);
-    } else if (ret == 2 || ret == 3) {
-        ptls_context_t ctx = {};
-        char fname[] = "/tmp/XXXXXXXX";
-        int fd, ret;
-        fd = mkstemp(fname);
-        if (fd < 0) {
-            goto out;
-        }
-        ret = write(fd, bytes, bytes_max);
-        if (ret != bytes_max) {
-            goto out2;
-        }
-        ctx.random_bytes = ptls_minicrypto_random_bytes;
-        ctx.get_time = &ptls_get_time;
-        ctx.key_exchanges = ptls_minicrypto_key_exchanges;
-        ctx.cipher_suites = ptls_minicrypto_cipher_suites;
-
-           if (ret == 2) {
-            ptls_load_certificates(&ctx, fname);
-            if (ctx.certificates.list) {
-                for (i = 0; i < ctx.certificates.count; i++) {
-                    if (ctx.certificates.list[i].base)
-                        free(ctx.certificates.list[i].base);
-                }
-                free(ctx.certificates.list);
-
-            }
-        } else {
-                   ptls_minicrypto_load_private_key(&ctx, fname);
-        }
-out2:
-        close(fd);
-        unlink(fname);
-    }
-out:
-    free(bytes);
-    return 0;
-}
