   237   */
   238
   239  static int ptls_compare_separator_line(const char *line, const char *begin_or_end, const char *label)
   240  {
   241      int ret = strncmp(line, "-----", 5);
   242      size_t text_index = 5;
   243
   244      if (ret == 0) {
   245          size_t begin_or_end_length = strlen(begin_or_end);
   246          ret = strncmp(line + text_index, begin_or_end, begin_or_end_length);
   247          text_index += begin_or_end_length;
   248      }
   249
   250      if (ret == 0) {
   251          ret = line[text_index] - ' ';
   252          text_index++;
   253      }
   254
   255      if (ret == 0) {
   256          size_t label_length = strlen(label);
   257          ret = strncmp(line + text_index, label, label_length);
   258          text_index += label_length;
   259      }
   260
   261      if (ret == 0) {
   262          ret = strncmp(line + text_index, "-----", 5);
   263      }
   264
   265      return ret;
   266  }
