   180  size_t ptls_asn1_get_expected_type_and_length(const uint8_t *bytes, size_t bytes_max, size_t byte_index, uint8_t expected_type,
   181                                                uint32_t *length, int *indefinite_length, size_t *last_byte, int *decode_error,
   182                                                ptls_minicrypto_log_ctx_t *log_ctx)
   183  {
   184      int is_indefinite = 0;
   185
   186      /* Check that the expected type is present */
   187      if (bytes[byte_index] != expected_type) {
   188          byte_index = ptls_asn1_error_message("Unexpected type", bytes_max, byte_index, 0, log_ctx);
   189          *decode_error = PTLS_ERROR_INCORRECT_ASN1_SYNTAX;
   190      } else {
   191          /* get length of element */
   192          byte_index++;
   193          byte_index =
   194              ptls_asn1_read_length(bytes, bytes_max, byte_index, length, &is_indefinite, last_byte, decode_error, 0, log_ctx);
   195
   196          if (indefinite_length != NULL) {
   197              *indefinite_length = is_indefinite;
   198          } else if (is_indefinite) {
   199              byte_index = ptls_asn1_error_message("Incorrect length for DER", bytes_max, byte_index, 0, log_ctx);
   200              *decode_error = PTLS_ERROR_DER_INDEFINITE_LENGTH;
   201          }
   202      }
   203
   204      return byte_index;
   205  }
